export type StudentImportAnalysis={batch_id:string;filename:string;total_rows:number;valid_rows:number;warning_rows:number;error_rows:number;can_execute:boolean;preview:Array<{row_number:number;status:'VALID'|'WARNING'|'ERROR';data:any;issues:Array<{level:string;code:string;field:string;message:string}>}>;preview_truncated:boolean};
export async function analyzeStudentImport(token:string,file:File,academicYearId:string):Promise<StudentImportAnalysis>{const q=new URLSearchParams({filename:file.name,academic_year_id:academicYearId});const r=await fetch(`${API}/import/students/analyze?${q}`,{method:'POST',headers:{...auth(token),'Content-Type':file.name.toLowerCase().endsWith('.csv')?'text/csv':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'},body:await file.arrayBuffer()});if(!r.ok)throw new Error(await errorDetail(r,'Analyse import impossible'));return r.json()}
export async function executeStudentImport(token:string,batchId:string,acceptWarnings:boolean){const r=await fetch(`${API}/import/students/batches/${batchId}/execute`,{method:'POST',headers:mutationHeaders(token),body:JSON.stringify({accept_warnings:acceptWarnings,confirm_separate_households:true})});if(!r.ok)throw new Error(await errorDetail(r,'Import impossible'));return r.json()}
